import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class EstimationDemo {

    private static final Logger log = Logger.getLogger(EstimationDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Calibrating estimates after an underestimate at " + BANK_NAME);

        EstimationTracker tracker = new EstimationTracker();
        // Past tasks: estimated vs actual days. Note the multi-currency blow-up.
        tracker.record(new TaskRecord("Add transfer validation", new BigDecimal("1"), new BigDecimal("2")));
        tracker.record(new TaskRecord("Multi-currency support", new BigDecimal("2"), new BigDecimal("12")));
        tracker.record(new TaskRecord("Statement PDF export", new BigDecimal("3"), new BigDecimal("5")));

        BigDecimal factor = tracker.calibrationFactor();
        log.info(() -> "Historical calibration factor (actual/estimate): " + factor);

        // A fresh raw estimate for a new feature — optimistic as usual.
        BigDecimal rawEstimate = new BigDecimal("2");
        BigDecimal calibrated = tracker.calibrate(rawEstimate);
        log.warning(() -> "Raw estimate " + rawEstimate + " days is optimistic.");
        log.info(() -> "Calibrated estimate: " + calibrated + " days — commit to this instead.");
    }
}

// ─── Would be in model/TaskRecord.java in a real project ───
class TaskRecord {
    private final String name;
    private final BigDecimal estimatedDays;
    private final BigDecimal actualDays;

    TaskRecord(String name, BigDecimal estimatedDays, BigDecimal actualDays) {
        this.name = name;
        this.estimatedDays = estimatedDays;
        this.actualDays = actualDays;
    }

    String getName() { return name; }
    BigDecimal getEstimatedDays() { return estimatedDays; }
    BigDecimal getActualDays() { return actualDays; }
}

// ─── Would be in tracker/EstimationTracker.java in a real project ───
class EstimationTracker {
    private static final Logger log = Logger.getLogger(EstimationTracker.class.getName());
    private final List<TaskRecord> records = new ArrayList<>();

    void record(TaskRecord record) {
        records.add(record);
        log.fine(() -> "Recorded " + record.getName() + ": est="
                + record.getEstimatedDays() + " actual=" + record.getActualDays());
    }

    // Average of (actual / estimated) across all recorded tasks.
    BigDecimal calibrationFactor() {
        if (records.isEmpty()) {
            return BigDecimal.ONE;
        }
        BigDecimal sumRatio = BigDecimal.ZERO;
        for (TaskRecord r : records) {
            BigDecimal ratio = r.getActualDays()
                    .divide(r.getEstimatedDays(), 4, RoundingMode.HALF_EVEN);
            sumRatio = sumRatio.add(ratio);
        }
        return sumRatio.divide(new BigDecimal(records.size()), 2, RoundingMode.HALF_EVEN);
    }

    // Apply the calibration factor to a fresh raw estimate.
    BigDecimal calibrate(BigDecimal rawEstimate) {
        return rawEstimate.multiply(calibrationFactor()).setScale(1, RoundingMode.HALF_EVEN);
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
